const cmds = [
  ["i1988", "sed -n '1,240p' /home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/inbox/local/items/I-1988.yaml", "."],
  ["protections", "\"$HORIZON_BIN\" inbox list --mine --status open --kind protection --json", "."],
  ["roadmap_list_help", "\"$HORIZON_BIN\" roadmap list --help", "."],
  ["graph_list_help", "\"$HORIZON_BIN\" graph -p Algebraic-Jacobian-Challenge-Rebuild list --help", "."],
  ["blueprint_files", "rg --files blueprint | sort", "."],
  ["hgraph_files", "find hgraph -maxdepth 3 -type f -print | sort", "."]
];
const results = await Promise.all(cmds.map(async ([name, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms:10000, max_output_tokens:30000});
  return `--- ${name} ---\n${r.output}`;
}));
results.forEach(text);

const targets=[
"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects",
"/home/axel/LeanAlgebraicGeometry-Horizon/SubProjects",
"/home/axel/LeanAlgebraicGeometry-Horizon/.claude/skills",
"/home/axel/LeanAlgebraicGeometry-Horizon/scripts",
"/home/axel/LeanAlgebraicGeometry-Horizon/tools",
"/home/axel/Archon-Horizon/src/archon_horizon"
];
const rs=await Promise.all(targets.map(t=>tools.exec_command({
 cmd:"rg -n -S -g '*.tex' -g '*.sty' -g '*.lean' -g '*.md' -g '*.py' -g '*.ts' -g '*.tsx' -g '*.sh' -e '\\bREFERENCE\\b' -e '\\bADAPTED\\b' -e '\\bCUSTOM\\b' -e 'TO CHECK' .",
 workdir:t,yield_time_ms:30000,max_output_tokens:30000
})));
for(let i=0;i<rs.length;i++) text(`${targets[i]}\n${rs[i].output}`);

const cmds = [
  ["bp_files", "find blueprint -type f -print | sort", "."],
  ["bp_includes", "rg -n '\\\\(input|include)\\{' blueprint --glob '*.tex'", "."],
  ["bp_structure", "for f in blueprint/src/*.tex blueprint/src/chapters/*.tex; do test -f \"$f\" && wc -l \"$f\"; done", "."],
  ["labels", "rg -n '\\\\label\\{' blueprint/src/chapters --glob '*.tex' | sed -n '1,260p'", "."],
  ["env_counts", "rg -n '^\\\\begin\\{(theorem|lemma|proposition|corollary|definition|remark|example|notation|convention|proof)\\}' blueprint/src/chapters --glob '*.tex' | cut -d: -f1,3 | sort | uniq -c", "."],
  ["macros", "rg -n '\\\\(source|lean|uses|leanok|mathlibok|notready)(\\{|\\b)' blueprint/src/chapters --glob '*.tex' | sed -n '1,320p'", "."]
];
const results = await Promise.all(cmds.map(async ([name, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms:10000, max_output_tokens:40000});
  return `--- ${name} ---\n${r.output}`;
}));
results.forEach(text);

