   692	const TAG_RE = /^(SOURCE QUOTE PROOF|SOURCE QUOTE|SOURCE|NOTE|TODO|FIXME)\b\s*:?\s*/i;
   693	function parseCommentEntries(value: string): { tag: string; text: string }[] {
   694	  const entries: { tag: string; text: string }[] = [];
   695	  let cur: { tag: string; text: string } | null = null;
   696	  for (const line of value.split('\n')) {
   697	    const m = TAG_RE.exec(line);
   698	    if (m) { if (cur) entries.push(cur); cur = { tag: m[1].toUpperCase(), text: line.slice(m[0].length) }; }
   699	    else if (cur) cur.text += '\n' + line;
   700	    else cur = { tag: '', text: line };

